function validate([nums, l, r]) {
  if (!Array.isArray(nums) || nums.length < 1 || nums.length > 20000) return 'nums needs 1 to 20000 values.';
  if (nums.some(v => !Number.isInteger(v) || v < 0 || v > 20000)) return 'Each value is an integer from 0 to 20000.';
  if (nums.reduce((a, b) => a + b, 0) > 20000) return 'The values of nums must add up to at most 20000.';
  if (!Number.isInteger(l) || !Number.isInteger(r) || l < 0 || l > r || r > 20000) return 'Need 0 <= l <= r <= 20000.';
  return null;
}

