function countSubMultisets(nums, l, r) {
  const MOD = 1_000_000_007;
  const count = new Map();
  let total = 0;
  for (const num of nums) {
    count.set(num, (count.get(num) ?? 0) + 1);
    total += num;
  }
  const zeros = count.get(0) ?? 0;
  count.delete(0);
  const limit = Math.min(r, total);
  // dp[s] = number of sub-multisets of the values seen so far with sum s.
  let dp = new Array(limit + 1).fill(0);
  dp[0] = 1;
  for (const [value, times] of count) {
    const next = dp.slice();
    const span = value * (times + 1);
    for (let s = value; s <= limit; s++) {
      next[s] = (next[s - value] + dp[s]) % MOD;
      if (s >= span) {
        next[s] = (next[s] - dp[s - span] + MOD) % MOD;
      }
    }
    dp = next;
  }
  let answer = 0;
  for (let s = l; s <= limit; s++) {
    answer = (answer + dp[s]) % MOD;
  }
  return (answer * (zeros + 1)) % MOD;
}

