function countSubMultisets(nums, l, r) {
  // Try every subset of positions and keep the distinct sorted bags.
  const n = nums.length;
  const seen = new Set();
  let result = 0;
  for (let mask = 0; mask < (1 << n); mask++) {
    const bag = [];
    for (let i = 0; i < n; i++) if (mask & (1 << i)) bag.push(nums[i]);
    bag.sort((a, b) => a - b);
    const key = bag.join(',');
    if (seen.has(key)) continue;
    seen.add(key);
    const sum = bag.reduce((a, b) => a + b, 0);
    if (sum >= l && sum <= r) result++;
  }
  return result % 1_000_000_007;
}

