function generate(rand, size) {
  if (size === 'small') {
    const n = 1 + Math.floor(rand() * 10);
    const top = 1 + Math.floor(rand() * 7);
    const nums = Array.from({ length: n }, () => Math.floor(rand() * (top + 1)));
    const total = nums.reduce((a, b) => a + b, 0);
    const r = Math.floor(rand() * (total + 3));
    const l = Math.floor(rand() * (r + 1));
    return [nums, l, r];
  }
  const cap = 20000;
  const maxValue = 20 + Math.floor(rand() * 400);
  const nums = [];
  let total = 0;
  while (nums.length < 2000) {
    const value = Math.floor(rand() * rand() * (maxValue + 1));
    if (total + value > cap) break;
    nums.push(value);
    total += value;
  }
  const r = rand() < 0.3 ? cap : Math.floor(rand() * (total + 1));
  const l = Math.floor(rand() * (Math.min(r, total) + 1));
  return [nums, l, r];
}
